void hostap_check_sta_fw_version ( struct ap_data * ap , int sta_fw_ver ) { if ( ! ap ) { return ; } if ( sta_fw_ver == PRISM2_FW_VER ( 0 , 8 , 0 ) ) { PDEBUG ( DEBUG_AP , "Using data::nullfunc ACK workaround - " "firmware upgrade recommended\n" ) ; } else { ap -> nullfunc_ack = 0 ; } if ( sta_fw_ver == PRISM2_FW_VER ( 1 , 4 , 2 ) ) { printk ( KERN_WARNING "%s: Warning: secondary station firmware " "version 1.4.2 does not seem to work in Host AP mode\n" , ap -> local -> dev -> name ) ; } } 